document.addEventListener("click",function(a){if(!a.defaultPrevented){var t=a.target&&a.target.closest?a.target.closest(".lang-switch [data-lang]"):null;t&&"1"!==t.dataset.langBound&&function(a){var t="en"===a?"/en":"/vi";if(((location.pathname||"/").replace(/\/+$/,"")||"/")!==t){try{localStorage.setItem("pl-lang",a)}catch(a){}var e=location.pathname||"/";/^\/(?:(?:vi|vn|en)\/?)?$/i.test(e)?location.href=t+location.search+(location.hash||""):location.reload()}}("en"===t.dataset.lang?"en":"vi")}});